const i={asOf:{en:"Point-in-time cutoff. The simulation may use only information that was already known at or before this timestamp.",zh:"时点截止线。仿真只能读取在该时间或更早已经可见的信息。"},instrument:{en:"Synthetic instrument identifier used inside the matching engine. It is not a live tradable ticker or a market-data subscription.",zh:"撮合引擎内部使用的合成证券标识，不代表实时可交易代码或行情订阅。"},benchmark:{en:"Synthetic reference series used to separate broad-market movement from instrument-specific movement.",zh:"用于区分大盘共同变动与目标证券特异变动的合成基准序列。"},initialPrice:{en:"Starting synthetic price shared by the baseline and intervention paths. It sets scale, not a forecast.",zh:"基准与干预路径共用的合成起始价格，只用于设定量级，不是预测。"},tickSize:{en:"Smallest price increment accepted by the order book. Smaller ticks allow finer price quotes.",zh:"订单簿允许的最小价格变动单位；越小，报价粒度越细。"},feeBps:{en:"Transaction fee in basis points. One basis point is 0.01%; fees affect cash and agent incentives.",zh:"以基点计的交易费用。1 bps = 0.01%，费用会影响现金与智能体交易动机。"},latencyMs:{en:"Base order-processing delay in simulated milliseconds. It affects queue timing, not wall-clock runtime.",zh:"以合成毫秒计的基础订单处理延迟，影响排队时序，不代表真实运行耗时。"},priceCollarBps:{en:"Maximum allowed price distance from the reference before an order is blocked or bounded, measured in basis points.",zh:"订单相对参考价允许偏离的最大范围，以基点计；越界订单会被阻止或限制。"},openingAuction:{en:"When enabled, initial orders cross in an opening call auction before continuous trading begins.",zh:"开启后，连续交易前先用开盘集合竞价撮合初始订单。"},volatilityHalt:{en:"When enabled, deterministic price-move rules can pause matching for a bounded number of simulation steps.",zh:"开启后，确定性价格波动规则可暂停若干仿真步的撮合。"},populationSize:{en:"Total number of simulated market agents. Larger populations increase behavioral diversity and compute time.",zh:"参与合成市场的智能体总数；数量越大，行为多样性与计算开销通常越高。"},populationProfile:{en:"Versioned mix of rule-agent archetypes and balance-sheet defaults used to construct the population.",zh:"用于生成智能体人口的规则型角色组合与资产负债默认值版本。"},institutionalShare:{en:"Fraction from 0 to 1 assigned institutional execution behavior. For example, 0.20 means 20%.",zh:"采用机构执行行为的比例，范围 0–1；例如 0.20 表示 20%。"},representativeLlmAgents:{en:"Number of representative agents whose evidence-bound cognition may be updated by the LLM. The remaining agents stay deterministic.",zh:"可由 LLM 更新证据约束认知的代表性智能体数量；其余智能体仍使用确定性规则。"},leverage:{en:"Allows agents to use margin subject to deterministic limits, which can introduce deleveraging and liquidation cascades.",zh:"允许智能体在确定性限制下使用保证金，从而可能产生去杠杆和强平链。"},shortSelling:{en:"Allows borrowed short positions subject to inventory and margin constraints.",zh:"允许在借券库存与保证金约束下建立空头头寸。"},cognitionMode:{en:"Rule only is fully deterministic. Hybrid LLM freezes bounded cognition signals first; risk controls and matching still own orders and prices.",zh:"仅规则模式完全确定；混合 LLM 先冻结有限认知信号，但订单、风控和价格仍由确定性机制负责。"},model:{en:"Zhipu model used only for approved evidence extraction or representative cognition. Unpriced models are blocked by the cost gate.",zh:"仅用于已批准证据抽取或代表性认知的智谱模型；无法核验价格的模型会被费用闸门阻止。"},decisionInterval:{en:"Number of simulation steps between cognition updates for each representative. A larger interval produces fewer model calls.",zh:"每个代表性节点两次认知更新之间的仿真步数；间隔越大，模型调用越少。"},callBudget:{en:"Hard upper bound on total LLM calls used to create the frozen cognition tape, not a per-seed allowance.",zh:"生成冻结认知序列时允许的 LLM 总调用硬上限，不是每个随机种子的额度。"},costCap:{en:"Maximum model-cost liability in USD. It is a fail-closed ceiling based on verified list prices, not a bill estimate.",zh:"以美元计的模型费用责任硬上限；按核验后的刊例价保守预留，不是预计账单。"},ruleFallback:{en:"If enabled, a failed LLM decision is explicitly replaced with the deterministic rule policy and recorded in the result.",zh:"开启后，LLM 决策失败会显式降级到确定性规则策略，并记录在结果中。"},topology:{en:"Graph family that determines who can pass information to whom. Different topologies change clustering and reach.",zh:"决定信息可在谁与谁之间传播的网络结构；不同拓扑会改变聚集性与触达范围。"},averageDegree:{en:"Average number of information-network neighbors per agent. Higher values generally spread information faster.",zh:"每个智能体在信息网络中的平均邻居数量；数值越高通常传播越快。"},rewiringProbability:{en:"Chance of replacing a local edge with a long-range edge in a Watts–Strogatz network. It has no effect on other topologies.",zh:"Watts–Strogatz 网络中把局部连接改为远程连接的概率；对其他拓扑不生效。"},echoChamberStrength:{en:"Strength of like-minded reinforcement in clustered or echo-style networks. Higher values slow cross-group correction.",zh:"聚集或回音室网络中的同质强化强度；越高通常越不利于跨群体纠正。"},correctionReach:{en:"Fraction of reached agents that can receive an approved correction once it enters the network.",zh:"已批准更正进入网络后可触达的智能体比例。"},baselineValue:{en:"Control value used in every baseline path. For multiplier parameters, 1.0 means the default intensity.",zh:"所有基准路径使用的对照值；对倍数型参数，1.0 表示默认强度。"},interventionValue:{en:"The one changed value used in intervention paths. Reported deltas are intervention minus baseline within each matched seed.",zh:"干预路径中唯一改变的值；所有差异均在同一配对随机种子内按“干预−基准”计算。"},matchedSeeds:{en:"Each seed creates one baseline/intervention pair with shared named random streams, reducing noise in their difference.",zh:"每个随机种子生成一组共享命名随机流的“基准/干预”路径，以降低差异中的随机噪声。"},simulationSteps:{en:"Number of abstract market-engine steps per path. A step is not a second, minute, or trading day.",zh:"每条路径运行的抽象市场引擎步数；一步不等于真实的一秒、分钟或交易日。"},rootSeed:{en:"Root value used to derive reproducible named random streams. Changing it changes the sample, not model quality.",zh:"用于派生可复现命名随机流的根值；改变它会改变样本，但不代表模型质量变化。"},primaryOutcome:{en:"Single preregistered metric used for the main stopping and interpretation decision. Secondary metrics remain explanatory.",zh:"用于主要停止与解释决策的唯一预注册指标；次要指标只用于辅助解释。"},minimumPairs:{en:"Minimum number of valid baseline/intervention seed pairs required before the stopping rule may finish.",zh:"停止规则允许结束前必须完成的最少有效“基准/干预”随机种子配对数。"},targetCiHalfWidth:{en:"Optional precision target in the primary metric’s unit. Leave blank to run the fixed maximum number of seed pairs.",zh:"以主要指标单位表示的可选精度目标；留空则运行固定的最大配对数。"},maxOutputTokens:{en:"Maximum tokens the provider may generate in one structured response. It contributes to the pre-dispatch cost reservation.",zh:"供应商单次结构化响应允许生成的最大 token 数，也会计入调用前费用预留。"},thinkingMode:{en:"Provider reasoning mode for supported models. It may improve difficult transformations but can increase latency and token use.",zh:"受支持模型的推理模式；可能改善复杂转换，但也可能增加延迟与 token 使用。"},baseline:{en:"Median value across valid baseline paths for the matched seeds.",zh:"所有有效配对随机种子的基准路径结果中位数。"},intervention:{en:"Median value across valid intervention paths for the same matched seeds.",zh:"同一组有效配对随机种子的干预路径结果中位数。"},delta:{en:"Median of the within-seed differences: intervention minus baseline.",zh:"每个随机种子内“干预−基准”差异的中位数。"},interval:{en:"2.5th–97.5th empirical quantile interval of seed-level paired differences; it is not the bootstrap confidence interval.",zh:"随机种子级配对差异的 2.5%–97.5% 经验分位区间，不是 bootstrap 置信区间。"},sampleSize:{en:"Number of valid matched seed pairs included after exclusions.",zh:"排除无效运行后纳入分析的有效配对随机种子数量。"},directionConsistency:{en:"Share of seed-level differences with the same sign as the overall median difference.",zh:"随机种子级差异与总体中位差异方向一致的比例。"},excludedRuns:{en:"Paths removed by deterministic invariants or validity rules; exclusions are reported rather than silently imputed.",zh:"因确定性不变量或有效性规则而排除的路径；系统报告排除，不会静默填补。"},maxDrawdownPct:{en:"Largest peak-to-trough percentage decline within a path. More negative or larger magnitude means a deeper drawdown.",zh:"单条路径中从峰值到谷值的最大百分比跌幅；绝对值越大表示回撤越深。"},realizedVolatilityPct:{en:"Annualization-free dispersion of simulated step returns, reported as a percentage for relative comparison.",zh:"合成步收益率的离散程度，以百分比表示，仅用于情景间相对比较，不做真实年化。"},maxSpreadBps:{en:"Largest bid–ask spread observed in the path, measured in basis points. Higher values indicate worse trading liquidity.",zh:"路径内观察到的最大买卖价差，以基点计；越高通常表示交易流动性越差。"},minDepth:{en:"Minimum remaining quantity across the first three bid and ask levels. Lower values indicate a thinner order book.",zh:"买卖盘前三档剩余数量合计的路径最小值；越低表示订单簿越薄。"},recoverySteps:{en:"Steps after the trough until price returns to 99.5% of its pre-shock level and spread returns below its recovery threshold.",zh:"触底后价格回到冲击前 99.5%，且价差回到恢复阈值以内所需的仿真步数。"},totalVolume:{en:"Total matched quantity over the path. It measures simulated activity, not real-market shares or dollars.",zh:"路径内的总撮合数量，衡量合成交易活跃度，不代表真实市场股数或金额。"},orderImbalance:{en:"Normalized difference between buy and sell pressure. The sign shows direction; magnitude shows concentration.",zh:"买入与卖出压力的归一化差；符号表示方向，绝对值表示集中程度。"},cascadeScore:{en:"Synthetic 0–100 score combining directional concentration, stop-loss/liquidation share, and negative sentiment. It is not a calibrated probability.",zh:"由方向集中、止损/强平占比与负面情绪合成的 0–100 分，不是经过现实校准的概率。"},returnQuantile05Pct:{en:"Fifth percentile of simulated path returns; about 5% of included paths are at or below this value.",zh:"合成路径收益率的 5% 分位数；约 5% 的纳入路径位于该值或更低。"},returnQuantile01Pct:{en:"First percentile of simulated path returns, describing a more extreme synthetic downside tail.",zh:"合成路径收益率的 1% 分位数，用于描述更极端的合成下行尾部。"},expectedShortfallPct:{en:"Average return among paths beyond the configured downside quantile. It is a synthetic tail summary, not forecast loss.",zh:"超过设定下行分位阈值的路径平均收益，是合成尾部摘要，不是预测损失。"},drawdownDurationSteps:{en:"Number of simulation steps spent below the previous peak before recovery.",zh:"从跌破前期峰值到恢复期间持续低于峰值的仿真步数。"},relativeSpreadBps:{en:"Quoted spread relative to the current mid-price, reported in basis points.",zh:"相对当前中间价归一化的报价价差，以基点表示。"},effectiveSpreadBps:{en:"Execution-price distance from the contemporaneous mid-price, doubled and reported in basis points.",zh:"成交价相对同时刻中间价距离的两倍，以基点表示。"},depth10Bps:{en:"Remaining order quantity priced within 10 basis points of the mid-price.",zh:"中间价上下 10 个基点范围内的剩余订单数量。"},depth25Bps:{en:"Remaining order quantity priced within 25 basis points of the mid-price.",zh:"中间价上下 25 个基点范围内的剩余订单数量。"},amihudIlliquidity:{en:"Synthetic absolute return per unit of traded volume. Higher values indicate more price movement for the same activity.",zh:"单位成交量对应的合成绝对收益变动；越高表示同等交易活动带来更大价格移动。"},kyleImpactProxy:{en:"Synthetic price-change sensitivity to signed order flow. It is a mechanism proxy, not an empirical Kyle estimate.",zh:"价格变化对带方向订单流的合成敏感度，是机制代理量，不是经验 Kyle 系数估计。"},orderToTradeRatio:{en:"Submitted orders divided by completed trades. Higher values indicate more messages per execution.",zh:"提交订单数除以完成成交数；越高表示每笔成交对应更多订单消息。"},cancellationRate:{en:"Share of submitted orders cancelled before a fill.",zh:"提交后在成交前被撤销的订单比例。"},fillRate:{en:"Share of submitted order quantity that executed in the synthetic order book.",zh:"提交订单数量中在合成订单簿实际成交的比例。"},rejectionRate:{en:"Share of submitted orders rejected by deterministic market or ledger controls.",zh:"被确定性市场或账本约束拒绝的提交订单比例。"},marketOrderShare:{en:"Share of submitted orders using immediately executable market-style instructions.",zh:"使用可立即成交的市价型指令的提交订单比例。"},averageQueueTime:{en:"Average simulation steps an executed order waited in the book before its fill.",zh:"已成交订单在订单簿中等待成交的平均仿真步数。"},herdingRate:{en:"Share of active agents choosing the dominant trade direction in the same step.",zh:"同一步中选择主导交易方向的活跃智能体比例。"},beliefDispersion:{en:"Cross-agent spread of internal belief scores. Higher values indicate greater disagreement.",zh:"智能体内部信念分数的横截面离散度；越高表示分歧越大。"},forcedLiquidations:{en:"Count of deterministic margin-rule events that forced an agent position to close.",zh:"确定性保证金规则触发智能体强制平仓的事件次数。"},systemEventsPerSecond:{en:"Backend simulation events processed per wall-clock second. It measures implementation throughput, not market speed.",zh:"后端每个真实秒处理的仿真事件数，衡量实现吞吐量，不代表市场速度。"},networkReachRate:{en:"Share of agents reached by the event information through the configured network.",zh:"事件信息通过已配置网络触达的智能体比例。"},informationDelaySteps:{en:"Average simulation steps between information availability and agent receipt.",zh:"信息可见到智能体收到信息之间的平均仿真步数。"},liquidityStressIndex:{en:"Composite relative indicator built from spread widening and depth loss. It is scenario-specific, not a market standard.",zh:"由价差扩大与深度下降合成的相对指标，是情景内部量尺，不是市场标准指数。"},tailLossProbability:{en:"Fraction of simulated paths crossing the configured synthetic tail-loss threshold; not a forecast probability.",zh:"越过合成尾部损失阈值的路径比例，不是对现实事件的预测概率。"},agentPnlDispersionCents:{en:"Cross-agent dispersion of end-of-path synthetic profit and loss, stored in cents.",zh:"路径结束时智能体合成损益的横截面离散度，以美分存储。"},systemEquityChangeCents:{en:"Aggregate change in synthetic agent equity from path start to finish, stored in cents.",zh:"从路径开始到结束的智能体合成权益总变化，以美分存储。"},forcedLiquidationVolume:{en:"Quantity executed because deterministic margin rules forced position liquidation.",zh:"因确定性保证金规则触发强制平仓而执行的数量。"},ledgerRejectedOrders:{en:"Orders rejected by deterministic cash, inventory, margin, collar, or other ledger controls.",zh:"被确定性现金、库存、保证金、价格保护带或其他账本约束拒绝的订单数。"},cognitiveOrderCount:{en:"Orders whose deterministic policy input included a frozen cognition signal. The LLM still did not submit the order directly.",zh:"确定性策略输入中包含冻结认知信号的订单数；LLM 仍未直接提交订单。"},benchmarkReturnPct:{en:"Synthetic benchmark return over the same path window.",zh:"同一路径窗口内的合成基准收益率。"},abnormalReturnPct:{en:"Instrument return minus synthetic benchmark return over the same window.",zh:"同一窗口内目标证券收益率减去合成基准收益率。"},haltCount:{en:"Number of deterministic volatility halts triggered in the path.",zh:"路径内触发确定性波动停牌的次数。"},haltedSteps:{en:"Total simulation steps spent in a halted market state.",zh:"市场处于停牌状态的仿真步数总计。"},totalFeesPaidCents:{en:"Total synthetic transaction fees charged to agents, stored in cents.",zh:"向智能体收取的合成交易费用总额，以美分存储。"}};function r(t,n){const e=i[t];if(e)return n==="zh-CN"?e.zh:e.en}export{r as g};
